          h: 'Язык генетики',
          html: String.raw`<ul>
<li><b>Ген</b> — участок ДНК, кодирующий один белок (признак). <b>Аллели</b> — варианты одного гена (A и a), лежат в одинаковых местах (локусах) гомологичных хромосом.</li>
<li><b>Доминантный</b> признак (A) проявляется у гетерозиготы, <b>рецессивный</b> (a) — только у гомозиготы aa.</li>
<li><b>Гомозигота</b> — AA или aa (один тип гамет), <b>гетерозигота</b> — Aa (два типа гамет).</li>
<li><b>Генотип</b> — совокупность генов, <b>фенотип</b> — совокупность признаков (зависит от генотипа и среды).</li>
</ul>
<div class="rule"><b>Законы Г. Менделя (1865):</b><br>1) закон единообразия гибридов первого поколения: AA × aa → все Aa;<br>2) закон расщепления: Aa × Aa → по фенотипу 3:1, по генотипу 1AA : 2Aa : 1aa;<br>3) закон независимого наследования: при дигибридном скрещивании гены из разных пар хромосом наследуются независимо, AaBb × AaBb → 9:3:3:1.<br><b>Закон чистоты гамет:</b> в каждую гамету попадает только один аллель из пары.</div>
<p><b>Неполное доминирование</b>: гетерозигота имеет промежуточный признак (ночная красавица: AA — красные, Aa — розовые, aa — белые), и тогда расщепление по фенотипу совпадает с генотипом — 1:2:1.</p>
<div class="trap"><b>Ловушка.</b> «Чистая линия» и «гомозигота» — синонимы в задачах. А если в условии сказано «в потомстве произошло расщепление», значит, хотя бы один родитель гетерозиготен.</div>`
