<p><b>Критерии вида:</b> морфологический (строение), физиологический (процессы жизнедеятельности), биохимический (белки, ДНК), генетический (кариотип — число и форма хромосом), экологический (условия обитания, пища), географический (ареал), этологический (поведение, брачные ритуалы).</p>
