          h: 'Экологические факторы',
          html: String.raw`<ul>
<li><b>Абиотические</b> — неживая природа: свет, температура, влажность, солёность, состав почвы.</li>
<li><b>Биотические</b> — влияние живых организмов: опыление, хищничество, конкуренция.</li>
<li><b>Антропогенные</b> — деятельность человека: вырубка лесов, распашка, удобрения, загрязнение.</li>
</ul>
<div class="rule"><b>Закон ограничивающего фактора:</b> выносливость организма определяется фактором, значение которого сильнее всего отклоняется от оптимума (находится в минимуме или максимуме). Диапазон значений фактора, в котором возможна жизнь, — <b>предел выносливости</b>; лучшая зона — <b>оптимум</b>.</div>
<p><b>Фотопериодизм</b> — реакция организмов на длину светового дня: листопад, перелёты птиц, цветение. Длина дня — самый надёжный сигнал смены сезонов.</p>`
