          html: String.raw`<p>Кожа состоит из трёх слоёв.</p>
<table class="tbl">
<tr><th>Слой</th><th>Что в нём</th></tr>
<tr><td>Эпидермис</td><td>эпителий: роговой слой (отшелушивается) и ростковый слой (деление клеток, меланин)</td></tr>
<tr><td>Дерма (собственно кожа)</td><td>соединительная ткань, сосуды, нервные окончания, потовые и сальные железы, корни волос</td></tr>
<tr><td>Подкожная жировая клетчатка</td><td>запас питательных веществ, амортизация, теплоизоляция</td></tr>
</table>
<div class="rule">Функции кожи: защитная, терморегуляция (испарение пота, изменение просвета сосудов), выделительная (пот: вода, соли, мочевина), рецепторная, синтез витамина D при облучении УФ.</div>
<p>При жаре сосуды кожи <b>расширяются</b>, потоотделение усиливается — организм теряет тепло. На холоде сосуды суживаются, теплоотдача снижается («гусиная кожа»).</p>
<div class="trap"><b>Ловушка.</b> Пот испаряется и охлаждает, только если он не «стекает». Сальные железы смазывают кожу и волосы, но не участвуют в терморегуляции. Закаливание — постепенное снижение температуры воды и воздуха.</div>
<div class="quick" data-a="дерма">Как называется слой кожи, в котором находятся потовые и сальные железы?</div>`
