<div class="rule">Гормоны — биологически активные вещества: действуют <b>дистанционно</b> на клетки-мишени, в <b>малых дозах</b>, высоко специфичны, быстро разрушаются, не видоспецифичны (инсулин свиньи действует у человека).</div>
