          html: String.raw`<p>Трубчатая кость состоит из <b>диафиза</b> (тело) и двух <b>эпифизов</b> (концы). Снаружи её покрывает <b>надкостница</b>; под ней — компактное вещество, внутри эпифизов — губчатое (красный костный мозг — кроветворение), в полости диафиза — жёлтый костный мозг (жир).</p>
<div class="rule">В толщину кость растёт за счёт деления клеток <b>надкостницы</b>, в длину — за счёт <b>хрящевой зоны роста</b> на границе диафиза и эпифиза (в детстве и юности).</div>
<p>Состав кости: органические вещества (оссеин) — упругость и гибкость; минеральные соли кальция и фосфора — твёрдость. У детей больше органики (кости гибкие, но искривляются), у пожилых — минеральных солей (хрупкие, легко ломаются).</p>
<div class="example"><p><b>Опыт.</b> Кость в растворе соляной кислоты становится гибкой (растворились минеральные соли). После прокаливания остаётся хрупкая кость (органика сгорела).</p></div>
<p>Соединения костей: неподвижные (швы черепа), полуподвижные (позвонки), подвижные (суставы: головка, впадина, суставной хрящ, суставная сумка и жидкость). Растяжение — повреждение связок, вывих — смещение суставных поверхностей, перелом — нарушение целости кости.</p>
<div class="trap"><b>Ловушка.</b> Красный костный мозг — в губчатом веществе (кроветворение), жёлтый — в полости диафиза. Кость растёт в длину не от надкостницы.</div>
<div class="quick" data-a="надкостница|надкостницы">За счёт какой структуры кость растёт в толщину?</div>`
